/* 06 prompt bar */
.composer{width:100%;max-width:460px;border:1px solid var(--line);background:var(--panel);position:relative;transition:border-color .3s ease}
.composer.focus{border-color:var(--icon-line)}
.chips{display:flex;flex-wrap:wrap;gap:6px;padding:12px 14px 0}
.chips:empty{display:none}
.ctx{display:inline-flex;align-items:center;gap:6px;padding:3px 8px;background:var(--chip);font-size:12px;font-weight:600;animation:iconin .35s var(--ease) both;transition:opacity .2s ease,transform .2s ease}
.ctx.leaving{opacity:0;transform:scale(.85)}
.ctx .ms{font-size:14px;color:var(--accent)}
.ctx button{color:var(--muted);font-size:13px;line-height:1}
.ta{display:block;width:100%;min-height:72px;resize:none;border:0;outline:0;background:transparent;color:var(--text);font:inherit;font-size:15px;line-height:1.5;padding:14px}
.ta::placeholder{color:var(--muted)}
.ta:focus-visible{outline:0}
#c6 .stage-inner{align-items:flex-end;padding-bottom:64px}
.comp-bar{display:flex;align-items:center;gap:6px;padding:8px 10px;border-top:1px solid var(--line)}
.ib{width:32px;height:32px;display:grid;place-items:center;color:var(--muted);border:1px solid var(--line);transition:color .25s,border-color .25s,background-color .25s}
.ib:hover{color:var(--text);border-color:var(--icon-line)}
.ib.rec{color:var(--accent);border-color:var(--accent);background-color:var(--accent-bg)}
.ib.rec .ms{animation:dot 1.2s ease-in-out infinite}
.model{display:inline-flex;align-items:center;gap:4px;height:32px;padding:0 8px;border:1px solid var(--line);font-family:var(--mono);font-weight:700;font-size:11px;text-transform:uppercase;color:var(--muted);transition:color .25s}
.model:hover{color:var(--text)}
.send{margin-left:auto;width:32px;height:32px;display:grid;place-items:center;background:var(--accent);color:#120a02;transition:opacity .3s ease,transform .3s var(--ease)}
.send[disabled]{opacity:.35;cursor:default}
.send:not([disabled]):active{transform:translateY(-2px)}
.menu{position:absolute;left:10px;right:10px;bottom:calc(100% + 6px);background:var(--panel);border:1px solid var(--icon-line);z-index:5;opacity:0;visibility:hidden;transform:translateY(6px) scale(.985);transform-origin:bottom center;transition:opacity .22s ease,transform .35s var(--ease),visibility 0s linear .35s}
.menu.show{opacity:1;visibility:visible;transform:none;transition:opacity .22s ease,transform .35s var(--ease),visibility 0s}
.menu-h{padding:8px 12px;border-bottom:1px solid var(--line)}
.menu-i{display:flex;align-items:center;gap:10px;width:100%;padding:9px 12px;font-size:13px;text-align:left;color:var(--text-dim);transition:background-color .2s ease,color .2s ease}
.menu-i .k{margin-left:auto}
.menu-i.act,.menu-i:hover{background-color:var(--accent-bg);color:var(--accent)}
.menu-i .ms{font-size:16px}
.composer.compact{display:flex;flex-wrap:wrap;align-items:flex-end}
.composer.compact .chips{width:100%}
.composer.compact .ta{flex:1;width:auto;min-height:44px;padding:11px 14px}
.composer.compact .comp-bar{border-top:0;padding:6px 8px}
.composer.compact .model,.composer.compact .at-btn{display:none}

/* composer attach menu */
.pb-att{left:8px;right:auto;bottom:52px;top:auto;width:300px}
.pb-att.show{opacity:1;visibility:visible;transform:none;pointer-events:auto}

/* ---------- 06 prompt bar ---------- */
const pb = $('#pb'), ta = $('#pb-ta'), menu = $('#pb-menu'), chips = $('#pb-chips'), send = $('#pb-send');
const sources = [['description','Onboarding flow.fig','Figma'],['description','Q3 research notes','Notion'],['tag','#design-reviews','Slack'],['link','designme.agency','Website']];
const cmds = [['edit_note','/summarise','Summarise the thread'],['search','/audit','Audit a design file'],['code','/handoff','Write handoff notes']];
const models = ['Opus 5.5','Sonnet 5.5','Haiku 4.5'];
let menuItems = [], menuIdx = 0, menuKind = null;
function openMenu(kind){
  menuKind = kind; menuIdx = 0;
  const list = kind === '@' ? sources : cmds;
  menu.innerHTML = `<div class="menu-h mono-xs">${kind === '@' ? 'Add a source' : 'Commands'}</div>` + list.map((it, i) => `<button class="menu-i ${i === 0 ? 'act' : ''}" role="option" data-i="${i}">${ic(it[0])}${it[1]}<span class="mono-xs k">${it[2]}</span></button>`).join('');
  menuItems = $$('.menu-i', menu);
  menuItems.forEach(b => b.addEventListener('mousedown', e => { e.preventDefault(); pick(+b.dataset.i); }));
  raf2(() => menu.classList.add('show'));
  Sound.play('open');
}
function closeMenu(){ if (!menuKind) return; menu.classList.remove('show'); menuKind = null; }
function addChip(icon, label){
  const c = document.createElement('span'); c.className = 'ctx';
  c.innerHTML = `${ic(icon)}${label}<button aria-label="Remove">×</button>`;
  c.querySelector('button').addEventListener('click', () => { Sound.play('tick'); c.classList.add('leaving'); setTimeout(() => morph(pb, () => c.remove()), 200); });
  morph(pb, () => chips.appendChild(c));
}
function pick(i){
  const v = ta.value, pos = v.lastIndexOf(menuKind);
  if (menuKind === '@'){ const s = sources[i]; addChip(s[0], s[1]); ta.value = v.slice(0, pos); }
  else { ta.value = v.slice(0, pos) + cmds[i][1] + ' '; }
  Sound.play('select'); closeMenu(); ta.focus(); update();
}
function update(){ send.disabled = !ta.value.trim(); }
function submit(){
  if (!ta.value.trim()) return;
  Sound.play('send'); showToast('Sent'); ta.value = '';
  morph(pb, () => { chips.innerHTML = ''; }); update();
}
ta.addEventListener('input', () => {
  update();
  const v = ta.value, last = v.slice(-1), prev = v.slice(-2, -1);
  if ((last === '@' || last === '/') && (!prev || /\s/.test(prev))) openMenu(last);
  else if (menuKind && (/\s$/.test(v) || !v.includes(menuKind))) closeMenu();
});
ta.addEventListener('keydown', e => {
  if (menuKind && menu.classList.contains('show')){
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp'){ e.preventDefault(); menuIdx = (menuIdx + (e.key === 'ArrowDown' ? 1 : -1) + menuItems.length) % menuItems.length; menuItems.forEach((b, i) => b.classList.toggle('act', i === menuIdx)); Sound.play('tick'); }
    else if (e.key === 'Enter'){ e.preventDefault(); pick(menuIdx); }
    else if (e.key === 'Escape'){ closeMenu(); Sound.play('close'); }
  } else if (e.key === 'Enter' && !e.shiftKey){ e.preventDefault(); submit(); }
});
ta.addEventListener('focus', () => pb.classList.add('focus'));
ta.addEventListener('blur', () => { pb.classList.remove('focus'); setTimeout(closeMenu, 120); });
$('#pb-at').addEventListener('click', () => { ta.focus(); ta.value += (ta.value && !/\s$/.test(ta.value) ? ' ' : '') + '@'; openMenu('@'); });
// model picker as a dropdown
const mBtn = $('#pb-model'), mMenu = document.createElement('div');
const modelInfo = { 'Opus 5.5':'Most capable', 'Sonnet 5.5':'Fast and balanced', 'Haiku 4.5':'Quickest replies' };
let mSel = 0;
mMenu.className = 'menu mdl-menu'; mMenu.setAttribute('role', 'listbox'); pb.appendChild(mMenu);
mBtn.setAttribute('aria-haspopup', 'listbox'); mBtn.setAttribute('aria-expanded', 'false');
function paintModels(){ mMenu.innerHTML = '<div class="menu-h mono-xs">Model</div>' + models.map((m, i) => `<button class="mdl-i ${i === mSel ? 'sel' : ''}" role="option" aria-selected="${i === mSel}" data-i="${i}"><span><span class="n">${m}</span><span class="d">${modelInfo[m]}</span></span>${ic('check')}</button>`).join(''); }
function openModels(open){
  if (open){ paintModels(); mMenu.style.left = mBtn.offsetLeft + 'px'; raf2(() => mMenu.classList.add('show')); }
  else mMenu.classList.remove('show');
  mBtn.setAttribute('aria-expanded', open); Sound.play(open ? 'open' : 'close');
}
mBtn.addEventListener('click', e => { e.stopPropagation(); openModels(!mMenu.classList.contains('show')); });
mMenu.addEventListener('click', e => { const b = e.target.closest('.mdl-i'); if (!b) return; mSel = +b.dataset.i; swapText($('#pb-model-name'), models[mSel]); Sound.play('select'); openModels(false); });
document.addEventListener('pointerdown', e => { if (mMenu.classList.contains('show') && !mMenu.contains(e.target) && !mBtn.contains(e.target)) openModels(false); });
document.addEventListener('keydown', e => { if (e.key === 'Escape' && mMenu.classList.contains('show')) openModels(false); });
$('#pb-mic').addEventListener('click', e => { const on = e.currentTarget.classList.toggle('rec'); Sound.play(on ? 'on' : 'off'); });
$$('#pb .ib:not(#pb-mic)').forEach(b => b.addEventListener('click', () => Sound.play('tick')));
send.addEventListener('click', submit);
tabHandlers.prompt = v => morph(pb, () => pb.classList.toggle('compact', v === 'compact'));

/* ---------- composer attach ---------- */
{
  const plus = $('#pb .comp-bar .ib'), file = document.createElement('input'); file.type = 'file'; file.hidden = true; pb.appendChild(file);
  const att = document.createElement('div'); att.className = 'menu pb-att'; att.setAttribute('role', 'menu'); pb.appendChild(att);
  const opts = [['upload','Upload a file','From your computer'],['description','Add from Figma','Onboarding flow.fig'],['link','Paste a link','designme.agency/pricing'],['grid_on','Attach a table','Q3 signups.csv']];
  att.innerHTML = `<div class="menu-h mono-xs">Attach</div>` + opts.map((o, i) => `<button class="menu-i" data-i="${i}">${ic(o[0])}<span>${o[1]}</span><span class="mono-xs" style="margin-left:auto">${o[2]}</span></button>`).join('');
  const close = () => att.classList.remove('show');
  plus.addEventListener('click', e => { e.stopPropagation(); att.classList.toggle('show'); Sound.play(att.classList.contains('show') ? 'open' : 'close'); });
  att.addEventListener('click', e => {
    const b = e.target.closest('.menu-i'); if (!b) return; const i = +b.dataset.i; close();
    if (i === 0){ file.click(); return; }
    addChip(opts[i][0], opts[i][2]); Sound.play('select'); update();
  });
  file.addEventListener('change', () => { if (file.files[0]){ addChip('description', file.files[0].name); Sound.play('select'); update(); } file.value = ''; });
  document.addEventListener('pointerdown', e => { if (att.classList.contains('show') && !att.contains(e.target) && e.target !== plus && !plus.contains(e.target)) close(); });
}
